class Solution {
  public int insertionTabsBossReceipt(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {for(int x:a[1]){int l=0,r=a[0].length;while(l<r){int m=(l+r)/2;if(a[0][m]<x)l=m+1;else r=m;}out.add(l);}}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
